#include "ViewerRuntime.h"
void CaptureV0412Ui(const fs::path&,HWND);
void RunV063SettingsTests(std::ostream& report){
    auto check=[&](bool ok,const char* text){if(!ok)throw std::runtime_error(text);report<<"PASS: v063 "<<text<<std::endl;};
    auto old=ParseViewerSettings(R"({"version":4,"darkTheme":true,"backgroundCopies":[{"path":"old.png","fingerprint":"0123456789abcdef0123456789abcdef"}]})");check(old.darkTheme&&old.backgroundThemes.empty(),"old history keeps the current theme without inventing a saved theme");
    ViewerSettings settings;settings.backgroundCopies={{L"背景A.png",L"0123456789abcdef0123456789abcdef"},{L"背景B.webp",L"1123456789abcdef0123456789abcdef"}};settings.backgroundThemes={{L"背景A.png",true},{L"背景B.webp",false}};auto read=ParseViewerSettings(SerializeViewerSettings(settings));check(read.backgroundCopies==settings.backgroundCopies&&read.backgroundThemes==settings.backgroundThemes,"per-image light and night settings roundtrip with Unicode paths");
    bool refused=false;try{ParseViewerSettings(R"({"version":4,"backgroundCopies":[{"path":"old.png","fingerprint":"0123456789abcdef0123456789abcdef","darkTheme":"bad"}]})");}catch(...){refused=true;}check(refused,"malformed history theme is rejected without silently changing preferences");
}
void RunV063UiTests(const fs::path& root,std::ostream& report){
    auto check=[&](bool ok,const char* text){if(!ok)throw std::runtime_error(text);report<<"PASS: v063 "<<text<<std::endl;};auto pump=[](){MSG m{};while(PeekMessageW(&m,nullptr,0,0,PM_REMOVE)){TranslateMessage(&m);DispatchMessageW(&m);}};auto wait=[&](auto ready){auto end=GetTickCount64()+20000;while(!ready()){pump();if(GetTickCount64()>end)throw std::runtime_error("v063 timeout");Sleep(10);}};
    KillTimer(app.window,RecordTimer);struct Restore{~Restore(){ClearBackdrop(false);app.darkTheme=false;ApplyTheme();Layout();SetTimer(app.window,RecordTimer,500,nullptr);}} restore;
    auto sample=root.parent_path().parent_path().parent_path()/L"Images"/L"back_img.webp";
    app.darkTheme=false;ApplyTheme();RequestBackdrop(sample.wstring());wait([&]{return !app.backgroundLoading;});auto a=app.backgroundPath;NewOptionsAction(6);check(app.darkTheme&&app.backgroundThemes.at(a),"manual night switch updates the active background preference");
    RequestBackdrop((root/L"v060-background.png").wstring());wait([&]{return !app.backgroundLoading;});auto b=app.backgroundPath;NewOptionsAction(6);check(!app.darkTheme&&!app.backgroundThemes.at(b),"manual light switch is recorded for a different background");
    RequestBackdrop((root/L"v060-background.jpg").wstring());wait([&]{return !app.backgroundLoading;});auto c=app.backgroundPath;auto order=app.backgroundCopies;auto disk=[&](){std::ifstream file(app.settings,std::ios::binary);return ParseViewerSettings(std::string((std::istreambuf_iterator<char>(file)),{}));};check(disk().backgroundCopies==order&&disk().backgroundThemes==app.backgroundThemes,"pruned history and all associated themes persist after background application");
    unsigned generation=app.backgroundGeneration;ShowBackdropDialog([&](HWND h){check(GetDlgItem(h,2810)&&GetDlgItem(h,2811)&&GetDlgItem(h,2812)&&!GetDlgItem(h,2813),"dialog has three native history thumbnail buttons");SendMessageW(h,WM_COMMAND,2812,0);check(Text(GetDlgItem(h,2803))==a&&Text(GetDlgItem(h,2805)).find(L"ナイト")!=std::wstring::npos,"history selection previews its path and saved night preference");check(app.backgroundPath==c&&!app.darkTheme,"preview selection does not change the main background or theme");CaptureV0412Ui(root/L"v063-history-light.png",h);SendMessageW(h,WM_COMMAND,IDCANCEL,0);});check(app.backgroundPath==c&&!app.darkTheme&&app.backgroundCopies==order&&app.backgroundGeneration==generation,"cancel preserves background, theme, history order and pending generation");
    auto count=[&]{size_t n=0;for(auto& entry:fs::directory_iterator(root))if(entry.path().filename().wstring().find(L"KuniVRCPhotEditor_Background_")==0)++n;return n;};auto before=count();
    ShowBackdropDialog([&](HWND h){SendMessageW(h,WM_COMMAND,2812,0);SendMessageW(h,WM_COMMAND,IDOK,0);});check(!app.darkTheme,"history theme is not applied before asynchronous image success");wait([&]{return !app.backgroundLoading;});check(app.backgroundPath==a&&app.darkTheme&&app.backgroundCopies.front().first==a&&count()==before,"successful history restore applies night mode, promotes the entry and reuses its file");
    ShowBackdropDialog([&](HWND h){check(Text(GetDlgItem(h,2810)).find(L"ナイト")!=std::wstring::npos,"current history button reports its stored night theme");SendMessageW(h,WM_COMMAND,2811,0);CaptureV0412Ui(root/L"v063-history-dark.png",h);SendMessageW(h,WM_COMMAND,IDCANCEL,0);});
    NewOptionsAction(6);std::ifstream input(app.settings,std::ios::binary);auto saved=ParseViewerSettings(std::string((std::istreambuf_iterator<char>(input)),{}));input.close();check(!app.darkTheme&&!saved.backgroundThemes.at(a)&&!saved.darkTheme,"manual preference survives the saved settings used at next startup");
    ClearBackdrop(false);app.backgroundCopies=saved.backgroundCopies;app.backgroundThemes=saved.backgroundThemes;app.darkTheme=saved.darkTheme;RequestBackdrop(saved.backgroundPath);wait([&]{return !app.backgroundLoading;});check(app.backgroundPath==a&&!app.darkTheme&&!app.backgroundThemes.at(a),"startup-style reload preserves the saved image and theme");
    // Deliberately diverge the global flag to exercise a same-file theme-only restoration.
    app.darkTheme=true;ApplyTheme();ShowBackdropDialog([&](HWND h){SendMessageW(h,WM_COMMAND,2810,0);SendMessageW(h,WM_COMMAND,IDOK,0);});wait([&]{return !app.backgroundLoading;});check(app.backgroundPath==a&&!app.darkTheme,"selecting the already-active path can still restore its saved light theme");
    NewOptionsAction(6);auto active=app.backgroundPath;RequestBackdrop((root/L"v060-bad.png").wstring(),0);wait([&]{return !app.backgroundLoading;});check(app.backgroundPath==active&&app.darkTheme,"failed history image decode cannot change the current theme");
    Result stale;stale.job.applyGeneration=app.backgroundGeneration-1;stale.job.backdropTheme=0;stale.job.backdropThemeRevision=app.backdropThemeRevision;stale.job.path=b;stale.pixels={1,1,{0,0,0,255}};AcceptBackdrop(stale);check(app.backgroundPath==active&&app.darkTheme,"obsolete image result cannot apply an obsolete theme");
    auto missing=app.backgroundCopies[1].first,hold=missing+L".v063-hold";check(MoveFileExW(missing.c_str(),hold.c_str(),MOVEFILE_WRITE_THROUGH)!=FALSE,"missing history image fixture prepared");struct ReturnFile{std::wstring from,to;~ReturnFile(){MoveFileExW(from.c_str(),to.c_str(),MOVEFILE_WRITE_THROUGH);}} returnFile{hold,missing};
    ShowBackdropDialog([&](HWND h){check(!IsWindowEnabled(GetDlgItem(h,2811)),"missing history image is visible but unavailable");SendMessageW(h,WM_COMMAND,IDCANCEL,0);});check(app.backgroundPath==active&&app.darkTheme,"unavailable history leaves the current image and theme intact");check(MoveFileExW(hold.c_str(),missing.c_str(),MOVEFILE_WRITE_THROUGH)!=FALSE,"missing image fixture restored");returnFile.from.clear();
    // A later manual switch supersedes a queued history theme, without cancelling its image.
    RequestBackdrop(b,0);NewOptionsAction(6);NewOptionsAction(6);wait([&]{return !app.backgroundLoading;});check(app.backgroundPath==b&&app.darkTheme&&app.backgroundThemes.at(b),"newer manual theme changes take precedence over queued history restoration");
    app.backgroundThemes.erase(b);SaveSettings(false);ShowBackdropDialog([&](HWND h){check(Text(GetDlgItem(h,2810)).find(L"未記録")!=std::wstring::npos,"legacy history is labelled as an unrecorded theme");SendMessageW(h,WM_COMMAND,2810,0);check(Text(GetDlgItem(h,2805)).find(L"現在")!=std::wstring::npos,"legacy history previews the current theme fallback");SendMessageW(h,WM_COMMAND,IDOK,0);});wait([&]{return !app.backgroundLoading;});check(app.darkTheme&&app.backgroundThemes.at(b),"applying legacy history records the current theme without guessing its past state");
    ShowBackdropDialog([&](HWND h){SendMessageW(h,WM_COMMAND,2802,0);SendMessageW(h,WM_COMMAND,IDOK,0);});check(!HasBackdrop()&&app.darkTheme&&!app.backgroundCopies.empty(),"clearing the background keeps the theme and recent history");
}
int V063Test(){auto root=app.settings.parent_path();std::ofstream report(root/L"v063-result.txt");try{RunV063SettingsTests(report);RunV060UiTests(root,report);RunV063UiTests(root,report);report<<"ALL PASSED\n";return 0;}catch(const std::exception& e){report<<"FAIL: "<<e.what()<<std::endl;return 1;}}
